import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { RouterWriter, WriterOptions } from "./types";
import { normalizeImportPath, toRoutePath } from "../resolver";
import type { RouteItem } from "../generator";

function formatMeta(meta: Record<string, unknown>): string {
    const json = JSON.stringify(meta, null, 2);
    const unquotedKeys = json.replace(/"([a-zA-Z_$][a-zA-Z0-9_$]*)":/g, "$1:");
    return unquotedKeys
        .split("\n")
        .map((line, idx) => (idx === 0 ? line : `    ${line}`))
        .join("\n");
}

export function reactRouterWriter(): RouterWriter {
    return {
        write(routes: RouteItem[], options: WriterOptions) {
            const { outputDir, fileName, importBase, pagesDir } = options;

            mkdirSync(outputDir, { recursive: true });

            const generateRouteBlock = (r: RouteItem) => {
                const lines = [
                    `  {`,
                    `    path: "${r.path || toRoutePath(r.file, pagesDir)}",`,
                    `    component: lazy(() => import(/* @vite-ignore */ "${importBase}/${normalizeImportPath(r.file)}"))`
                ];

                if (r.meta && Object.keys(r.meta).length > 0) {
                    lines.push(`    meta: ${formatMeta(r.meta)}`);
                }

                lines.push(`  }`);
                return lines.join("\n");
            };

            const content = [
                "// This file is auto-generated by @zarr20/rakit-routes",
                "// Do not edit this file manually",
                "",
                'import { lazy } from "react";',
                "",
                "const router = [",
                routes.map(generateRouteBlock).join(",\n"),
                "];",
                "",
                "export { router, router as routes };",
                "export default router;",
                ""
            ].join("\n");

            const filePath = join(outputDir, `${fileName}.tsx`);

            writeFileSync(filePath, content, { encoding: "utf-8" });

            console.log(`✔ Router file generated at: ${filePath}`);
        }
    };
}
